// This class is not documented; it is used internally by MacApp.// You never need to use it yourself.{public:	TCmdTable(ArrayIndex_AC initialSize = 0);	virtual ~TCmdTable();	virtual CompareResult_AC Compare(const MenuCmdRecord& record1,									 const MenuCmdRecord& record2) const;	ArrayIndex_AC FindFirstOf(CommandNumber theCommand) const;		// Find the first element with the command number. Does not support negative		// command numbers, which are mapped rather than stored in the table. 	void CommandToMenuItem(CommandNumber theCommand,						   MenuID& menu,						   short& item) const;		// Convert the command number into a menu resource ID and item number. 		// Works for all command numbers. 	CommandNumber CommandFromMenuItem(short menu,									  short item) const;		// Given a menuID,item # return the appropriate command number. 		// If there is no such command number, return -BOR(((menu) << 8), item). 		// If the item number is <0 then assume that it is a negative command number.	void AddCommand(CommandNumber commandNumber,					MenuID menuNumber,					short itemNumber);		// This adds a menu item/command number 	void InsertCommand(CommandNumber commandNumber,					   MenuID menuNumber,					   short itemNumber);		// This adds a menu item/command number after the menus have already been 		// set up, and increments the item numbers for the other commands after it		// in the same menu. 	void DeleteMenuCommand(CommandNumber theMenuItemCommandNumber);		// This deletes all the menu items with the command number after the menus 		// have already been set up, and decrements the item numbers for the other 		// commands after it in the same menu. protected:	static CompareResult_AC TestItem(const MenuCmdRecord& anRecord,									 void* yourDataPtr);};typedef TCmdTable::Iterator TCmdTableIterator;//========================================================================================// CLASS CCommandIterator//========================================================================================class EXPORT_MA CCommandIterator : public TCmdTableIterator{public:	CCommandIterator(const TCmdTable* inList, CommandNumber theCommand);	~CCommandIterator() {}	MenuCmdRecord* First();	MenuCmdRecord* Next();	MenuCmdRecord* operator++() { return Next(); }	MenuCmdRecord* operator++(int) { MenuCmdRecord* returnVal = Current(); Next(); return returnVal; }	operator MenuCmdRecord*() const { return Current(); }protected:	CommandNumber	fCommand;	MenuCmdRecord	fMenuCmdRecord;};//========================================================================================// GLOBAL Procedures//========================================================================================EXPORT_MA void Enable(MenuRef aMenuRef, short item, bool canDo);	// Enable or disable a menu item. EXPORT_MA void EnableCheck(MenuRef aMenuRef, short item, bool canDo, bool checkIt);	// Enable/ Disable and check/ uncheck a menu item. #endif // __UMenuCommandTable__